package com.ticketing.v3.reservation.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.ticketing.v3.reservation.repository.ReservationRepository;import com.ticketing.v3.reservation.domain.Hold;import com.ticketing.v3.seat.service.InventoryService;import com.ticketing.v3.performance.service.PerformanceService;import com.ticketing.v3.global.service.IdempotencyService;import com.ticketing.v3.global.exception.ApiException;import java.time.*;import java.util.*;import java.sql.Timestamp;
@Service public class ReservationService {
 private final ReservationRepository reservations;private final InventoryService inventory;private final PerformanceService performance;private final IdempotencyService idem;private final Clock clock;
 public ReservationService(ReservationRepository r,InventoryService i,PerformanceService p,IdempotencyService d,Clock c){reservations=r;inventory=i;performance=p;idem=d;clock=c;}
 public record CreateHold(long sessionId,List<Long> seatIds){}
 @Transactional public Object create(long user,CreateHold r,String key){if(r.seatIds()==null||r.seatIds().isEmpty()||r.seatIds().size()>4||r.seatIds().stream().anyMatch(s->s==null||s<=0)||new HashSet<>(r.seatIds()).size()!=r.seatIds().size())throw ApiException.bad("Select 1..4 distinct seats");var seats=r.seatIds().stream().sorted().toList();return idem.execute(user,"hold",key,r.sessionId()+":"+seats,()->{performance.requireSale(r.sessionId());var now=clock.instant();long id=reservations.create(user,r.sessionId(),now.plusSeconds(300));long total=inventory.claim(r.sessionId(),seats,id,now);reservations.attach(id,seats,total);return reservations.find(id,false).orElseThrow().hold();});}
 @Transactional(readOnly=true) public Map<String,Object> active(long user){return Map.of("items",reservations.activeIds(user,clock.instant()).stream().map(id->reservations.find(id,false).orElseThrow().hold()).toList());}
 public Hold owned(long user,long id,boolean lock){var found=reservations.find(id,lock).orElseThrow(ApiException::missing);if(found.user()!=user)throw ApiException.forbidden();return found.hold();}
 @Transactional public Hold get(long user,long id){Hold h=owned(user,id,true);if(h.status().equals("ACTIVE")&&!h.expiresAt().isAfter(clock.instant())){inventory.release(id);reservations.status(id,"EXPIRED");return new Hold(h.id(),h.sessionId(),h.seatIds(),h.expiresAt(),"EXPIRED",h.totalKrw(),h.paymentStatus());}return h;}
 @Transactional public void release(long user,long id){Hold h=owned(user,id,true);if(h.status().equals("CONFIRMED"))throw ApiException.conflict("ALREADY_CONFIRMED");if(h.status().equals("RELEASED")||h.status().equals("EXPIRED"))return;inventory.release(id);reservations.status(id,h.expiresAt().isAfter(clock.instant())?"RELEASED":"EXPIRED");}
 @Transactional public Hold payable(long user,long id){Hold initial=owned(user,id,false);performance.requireSale(initial.sessionId());Hold h=owned(user,id,true);if(!h.status().equals("ACTIVE")||!h.expiresAt().isAfter(clock.instant()))throw ApiException.conflict("HOLD_NOT_ACTIVE");return h;}
 @Transactional public long confirm(long user,Hold h){inventory.confirm(h.id(),h.sessionId(),h.seatIds());reservations.status(h.id(),"CONFIRMED");return reservations.reservation(h.id(),user,clock.instant());}
 public Map<String,Object> history(long user){return Map.of("items",reservations.history(user).stream().map(row->{var out=new LinkedHashMap<String,Object>(row);long hold=((Number)out.remove("holdId")).longValue();out.put("seatLabels",reservations.labels(hold));out.put("startsAt",((Timestamp)row.get("startsAt")).toInstant());out.put("status","CONFIRMED");return out;}).toList());}
}
